663	/** Produto agregado do dia (rede). */
664	export interface TvTopProduct {
665	  nome: string;
666	  quantidade: number;
667	  valor: number;
668	}
669	
670	/**
671	 * Top N produtos do dia da rede, agregando `degust_vendas_diarias` por nome.
672	 * Ranking por quantidade vendida (desempate por valor).
673	 */
674	export function topProductsFromDaily(
675	  rows: DailyProductRow[],
676	  n = 5,
677	): TvTopProduct[] {
678	  const byName = new Map<string, TvTopProduct>();
679	  for (const row of rows) {
680	    let agg = byName.get(row.degust_nome);
681	    if (!agg) {
682	      agg = { nome: row.degust_nome, quantidade: 0, valor: 0 };
683	      byName.set(row.degust_nome, agg);
684	    }
685	    agg.quantidade += row.quantidade ?? 0;
686	    agg.valor += row.valor_total ?? 0;
687	  }
688	  return [...byName.values()]
689	    .sort((a, b) => b.quantidade - a.quantidade || b.valor - a.valor)
690	    .slice(0, n);
691	}
