118	async function fetchTvContext(): Promise<TvContext> {
119	  const [lojasRes, degustRes] = await Promise.all([
120	    supabase
121	      .from('lojas')
122	      .select('id, nome, tipo')
123	      .eq('ativo', true)
124	      .order('id'),
125	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
126	  ]);
127	  if (lojasRes.error) throw lojasRes.error;
128	  if (degustRes.error) throw degustRes.error;
129	
130	  const lojas: TvLoja[] = lojasRes.data ?? [];
131	  const degustLojaIds = new Set<number>();
132	  const degustCodeToLoja = new Map<number, number>();
133	  for (const row of degustRes.data ?? []) {
134	    degustLojaIds.add(row.loja_id);
135	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
136	  }
137	
138	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
139	  const linxLojaIds = lojas
140	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
141	    .map((l) => l.id);
142	
143	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
144	}
