346	// ─────────────────────────────────────────────────────────────────────────────
347	
348	async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
349	  const today = toIsoDateLocal(new Date());
350	
351	  const loadDay = async (date: string) => {
352	    const { data, error } = await supabase
353	      .from('daily_production')
354	      .select('quantity')
355	      .is('loja_id', null)
356	      .eq('date', date)
357	      .limit(2000);
358	    if (error) throw error;
359	    return data ?? [];
360	  };
361	
362	  let refDate = today;
363	  let rows = await loadDay(today);
364	  if (rows.length === 0) {
365	    // Sem produção registrada hoje → mostra o último dia disponível
366	    const { data: latest, error } = await supabase
367	      .from('daily_production')
368	      .select('date')
369	      .is('loja_id', null)
370	      .lte('date', today)
371	      .order('date', { ascending: false })
372	      .limit(1);
373	    if (error) throw error;
374	    const lastDate = latest?.[0]?.date;
375	    if (!lastDate) return null;
376	    refDate = lastDate;
377	    rows = await loadDay(lastDate);
378	  }
379	
380	  return {
381	    dataReferencia: refDate,
382	    itens: rows.length,
383	    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
384	  };
385	}
386	
387	// ─────────────────────────────────────────────────────────────────────────────
388	// Top produtos do dia da rede (degust_vendas_diarias, SOMENTE hoje)
389	// ─────────────────────────────────────────────────────────────────────────────
390	
391	async function fetchTopProducts(ctx: TvContext): Promise<TvTopProduct[]> {
392	  const ids = [...ctx.degustLojaIds];
393	  if (ids.length === 0) return [];
394	  // O card é rotulado "TOP 5 PRODUTOS · HOJE": filtra `data` = hoje no fuso
395	  // LOCAL (mesmo `toIsoDateLocal` usado no resto do hook). Sem vendas hoje →
396	  // lista vazia (a UI mostra "aguardando vendas do dia"); nunca mostrar
397	  // ontem com rótulo de hoje.
398	  const today = toIsoDateLocal(new Date());
399	  const data = await fetchAllPages((from, to) =>
400	    supabase
401	      .from('degust_vendas_diarias')
402	      .select('degust_nome, quantidade, valor_total')
403	      .eq('data', today)
404	      .in('loja_id', ids)
405	      .order('id')
406	      .range(from, to),
407	  );
408	  return topProductsFromDaily(data, 5);
409	}
410	
411	// ─────────────────────────────────────────────────────────────────────────────
412	// Hook principal
413	// ─────────────────────────────────────────────────────────────────────────────
414	
415	/** Retorno do {@link useTvDashboardData}. */
416	export interface TvDashboardData {
417	  network: TvNetworkSummary | null;
418	  stores: TvStoreData[];
419	  factory: TvFactoryData | null;
420	  exceptions: TvExceptionsResult;
421	  topProducts: TvTopProduct[];
422	  freshness: TvFreshness;
423	  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
424	  isLoading: boolean;
425	  /** true quando o contexto falhou (painel não consegue montar). */
426	  isError: boolean;
427	}
428	
429	const EMPTY_MOVEMENT: TvMovementSummary = {
430	  entradas: 0,
431	  saidas: 0,
432	  ultimaBipagem: null,
433	};
434	
435	/**
436	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
437	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
438	 * `topProducts`, `freshness`). Vendas live re-buscam a cada 60s; o resto a
439	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
440	 */
441	export function useTvDashboardData(): TvDashboardData {
442	  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
443	  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
444	  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
445	  const tick = useMinuteClock();
446	
447	  const ctxQuery = useQuery({
448	    queryKey: tvDashboardKeys.context(),
449	    queryFn: fetchTvContext,
450	    staleTime: TV_QUERY_INTERVALS.slowMs,
451	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
452	  });
453	  const ctx = ctxQuery.data;
454	
455	  const liveQuery = useQuery({
456	    queryKey: tvDashboardKeys.liveSales(),
457	    queryFn: () => {
458	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
459	      return fetchLiveSales(ctx);
460	    },
461	    enabled: !!ctx,
462	    refetchInterval: TV_QUERY_INTERVALS.liveMs,
463	    staleTime: 30_000,
464	  });
465	
466	  const laggedQuery = useQuery({
467	    queryKey: tvDashboardKeys.laggedSales(),
468	    queryFn: () => {
469	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
470	      return fetchLaggedSales(ctx);
471	    },
472	    enabled: !!ctx,
473	    staleTime: TV_QUERY_INTERVALS.slowMs,
474	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
475	  });
476	
477	  const lastWeekQuery = useQuery({
478	    queryKey: tvDashboardKeys.lastWeekSales(),
479	    queryFn: () => {
480	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
481	      return fetchDegustLastWeek(ctx);
482	    },
483	    enabled: !!ctx,
484	    staleTime: TV_QUERY_INTERVALS.slowMs,
485	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
486	  });
487	
488	  const metasQuery = useQuery({
489	    queryKey: tvDashboardKeys.metas(),
490	    queryFn: fetchMetas,
491	    staleTime: TV_QUERY_INTERVALS.slowMs,
492	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
493	  });
494	
495	  const stockQuery = useQuery({
496	    queryKey: tvDashboardKeys.stock(),
497	    queryFn: fetchStockAlerts,
498	    staleTime: TV_QUERY_INTERVALS.slowMs,
499	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
500	  });
501	
502	  const movementsQuery = useQuery({
503	    queryKey: tvDashboardKeys.movements(),
504	    queryFn: fetchMovementsToday,
505	    staleTime: TV_QUERY_INTERVALS.slowMs,
506	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
507	  });
508	
509	  const factoryQuery = useQuery({
510	    queryKey: tvDashboardKeys.factoryProduction(),
511	    queryFn: fetchFactoryProduction,
512	    staleTime: TV_QUERY_INTERVALS.slowMs,
513	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
514	  });
515	
516	  const topQuery = useQuery({
517	    queryKey: tvDashboardKeys.topProducts(),
518	    queryFn: () => {
519	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
520	      return fetchTopProducts(ctx);
521	    },
522	    enabled: !!ctx,
523	    staleTime: TV_QUERY_INTERVALS.slowMs,
524	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
525	  });
526	
527	  return useMemo<TvDashboardData>(() => {
528	    const now = tick;
529	    const todayIso = toIsoDateLocal(now);
530	
531	    const stockDetail: Map<number, StockDetail> = buildStockSummary(
532	      stockQuery.data ?? [],
533	    );
534	    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
535	    const flashByLoja = new Map<number, FlashRow>(
536	      (liveQuery.data ?? []).map((f) => [f.loja_id, f]),
537	    );
538	    const laggedByLoja = new Map<number, LaggedSales>(
539	      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
540	    );
541	    const lastWeekByLoja = lastWeekQuery.data ?? new Map<number, number>();
542	    const lojaNomeById = new Map<number, string>(
543	      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
544	    );
545	
546	    // ── Cards de loja ──
547	    const stores: TvStoreData[] = (ctx?.lojas ?? [])
548	      .filter((l) => !isFactoryTipo(l.tipo))
549	      .map((loja) => {
550	        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
551	          ? 'degust-live'
552	          : 'linx-lagged';
553	        const stock = stockDetail.get(loja.id);
554	        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;
555	
556	        let vendas: TvSalesSnapshot | null = null;
557	        let metaDia: number | null = null;
558	        let pctMeta: number | null = null;
559	        let deltaSemana: number | null = null;
560	
561	        if (channel === 'degust-live') {
562	          const flash = flashByLoja.get(loja.id);
563	          if (flash) {
564	            vendas = {
565	              valor: flash.total_vendas,
566	              cupons: flash.total_cupons,
567	              ticketMedio: flash.ticket_medio,
568	              dataReferencia: todayIso,
569	              isLive: true,
570	              caixaAberto: flash.caixa_aberto,
571	              atualizadoEm: flash.ultima_atualizacao,
572	            };
573	            metaDia = metaFor(metasQuery.data, loja.id, now);
574	            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
575	            // Delta = "vs MESMO PONTO do dia na semana passada": a base do
576	            // mesmo dia anterior é pró-rateada pela fração da janela já
577	            // decorrida (mesma fração do pró-rata da meta). Comparar hoje
578	            // PARCIAL com semana passada COMPLETA inflava a queda de manhã.
579	            deltaSemana = weekOverWeekDelta(
580	              flash.total_vendas,
581	              proRataLastWeekBase(lastWeekByLoja.get(loja.id) ?? null, now),
582	            );
583	          }
584	        } else {
585	          const lagged = laggedByLoja.get(loja.id);
586	          if (lagged) {
587	            vendas = {
588	              valor: lagged.valor,
589	              cupons: null,
590	              ticketMedio: null,
591	              dataReferencia: lagged.dataReferencia,
592	              isLive: false,
593	              caixaAberto: null,
594	              atualizadoEm: null,
595	            };
596	            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
597	            const refDate = parseIsoDateLocal(lagged.dataReferencia);
598	            metaDia = metaFor(metasQuery.data, loja.id, refDate);
599	            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
600	            // Canal defasado: dia COMPLETO vs dia COMPLETO — sem pró-rata.
601	            deltaSemana = weekOverWeekDelta(
602	              lagged.valor,
603	              lagged.valorSemanaAnterior,
604	            );
605	          }
606	        }
607	
608	        const rag = classifyStoreRag({
609	          stockOutCount: stock?.zerados ?? 0,
610	          stockLowCount: stock?.abaixoMinimo ?? 0,
611	          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
612	          isLiveChannel: channel === 'degust-live',
613	          lastMovementAt: movement.ultimaBipagem,
614	          now,
615	        });
616	
617	        return {
618	          lojaId: loja.id,
619	          nome: loja.nome,
620	          channel,
621	          vendas,
622	          metaDia,
623	          pctMeta,
624	          deltaSemana,
625	          estoque: {
626	            zerados: stock?.zerados ?? 0,
627	            abaixoMinimo: stock?.abaixoMinimo ?? 0,
628	          },
629	          movimentacao: movement,
630	          rag: rag.status,
631	          ragReasons: rag.reasons,
632	        };
633	      });
634	
635	    // ── Card da fábrica ──
636	    let factory: TvFactoryData | null = null;
637	    if (ctx?.factoryLojaId != null) {
638	      const fid = ctx.factoryLojaId;
639	      const stock = stockDetail.get(fid);
640	      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
641	      const rag = classifyStoreRag({
642	        stockOutCount: stock?.zerados ?? 0,
643	        stockLowCount: stock?.abaixoMinimo ?? 0,
644	        pctMetaProRata: null,
645	        isLiveChannel: false,
646	        lastMovementAt: movement.ultimaBipagem,
647	        now,
648	        // Janela de PRODUÇÃO (06–18h, threshold 2h) — mesma do card visual
649	        hours: TV_FACTORY_HOURS,
650	        noMovementThresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
651	      });
652	      factory = {
653	        lojaId: fid,
654	        nome: lojaNomeById.get(fid) ?? 'Fábrica',
655	        producao: factoryQuery.data ?? null,
656	        expedicoes: movement,
657	        estoque: {
658	          zerados: stock?.zerados ?? 0,
659	          abaixoMinimo: stock?.abaixoMinimo ?? 0,
660	        },
661	        rag: rag.status,
662	        ragReasons: rag.reasons,
663	      };
664	    }
665	
666	    // ── Freshness ──
667	    // Classificada com `now` do tick de minuto: quando dataUpdatedAt para de
668	    // avançar (outage), a idade cresce e o chip escala pra âmbar mesmo sem
669	    // nenhum dado novo chegar. Os timestamps CRUS ficam expostos no retorno.
670	    const freshness: TvFreshness = buildFreshness(
671	      liveQuery.dataUpdatedAt,
672	      stockQuery.dataUpdatedAt,
673	      TV_QUERY_INTERVALS,
674	      now,
675	    );
676	
677	    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
678	    const allExceptions: TvException[] = buildStockExceptions(
679	      stockDetail,
680	      lojaNomeById,
681	    );
682	    // "Sem movimentação" derivada do DADO estruturado (última bipagem ×
683	    // janela), nunca por parsing de ragReasons — independe da cor do card
684	    // (aparece mesmo com card vermelho) e cobre também a fábrica.
685	    for (const store of stores) {
686	      const noMovement = buildNoMovementException({
687	        lojaId: store.lojaId,
688	        lojaNome: store.nome,
689	        lastMovementAt: store.movimentacao.ultimaBipagem,
690	        now,
691	      });
692	      if (noMovement) allExceptions.push(noMovement);
693	    }
694	    if (factory) {
695	      const noMovement = buildNoMovementException({
696	        lojaId: factory.lojaId,
697	        lojaNome: factory.nome,
698	        lastMovementAt: factory.expedicoes.ultimaBipagem,
699	        now,
700	        hours: TV_FACTORY_HOURS,
701	        thresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
702	      });
703	      if (noMovement) allExceptions.push(noMovement);
704	    }
705	    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
706	      const liveUpdatedAt = freshness.vendasLive.updatedAt;
707	      allExceptions.push({
708	        id: 'stale-data:vendas-live',
709	        kind: 'stale-data',
710	        severity: 'amber',
711	        lojaId: null,
712	        lojaNome: null,
713	        message: liveUpdatedAt
714	          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
715	          : 'Venda live ainda não carregou',
716	      });
717	    }
718	    const exceptions = sortAndLimitExceptions(allExceptions);
719	
720	    // ── Hero (rede) ──
721	    // Soma apenas lojas cujo dado é de HOJE (live) — não misturar dias.
722	    const liveStores = stores.filter(
723	      (s) => s.vendas?.isLive && s.vendas.dataReferencia === todayIso,
724	    );
725	    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
726	    const metasHoje = liveStores
727	      .map((s) => s.metaDia)
728	      .filter((m): m is number => m != null && m > 0);
729	    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
730	    const lastWeekTotal = liveStores.reduce(
731	      (s, st) => s + (lastWeekByLoja.get(st.lojaId) ?? 0),
732	      0,
733	    );
734	    const network: TvNetworkSummary | null = ctx
735	      ? {
736	          vendasHoje,
737	          metaDia,
738	          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
739	          // Mesmo critério do card live: delta "vs mesmo ponto do dia na
740	          // semana passada" (base pró-rateada pela fração da janela).
741	          deltaSemana: weekOverWeekDelta(
742	            vendasHoje,
743	            proRataLastWeekBase(lastWeekTotal, now),
744	          ),
745	          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
746	          lojasLive: liveStores.length,
747	          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
748	        }
749	      : null;
750	
751	    return {
752	      network,
753	      stores,
754	      factory,
755	      exceptions,
756	      topProducts: topQuery.data ?? [],
757	      freshness,
758	      isLoading: ctxQuery.isLoading,
759	      isError: ctxQuery.isError,
760	    };
761	  }, [
762	    // `tick` é o que faz staleness/RAG avançarem em outage total (sem ele a
763	    // classificação congelaria no último snapshot de dados).
764	    tick,
765	    ctx,
766	    ctxQuery.isLoading,
767	    ctxQuery.isError,
768	    liveQuery.data,
769	    liveQuery.dataUpdatedAt,
770	    laggedQuery.data,
771	    lastWeekQuery.data,
772	    metasQuery.data,
773	    stockQuery.data,
774	    stockQuery.dataUpdatedAt,
775	    movementsQuery.data,
776	    factoryQuery.data,
777	    topQuery.data,
778	  ]);
779	}
